const ids = ["G01","G02","G03","G04","G05","G06"];
const out = [];
for (const id of ids){
  const p = await tools.origin_packet({case_id:id});
  const c = p.packet.cases[0];
  const ev = c.evidence;
  const src = new Map(ev.material_index.map(m=>[m.id,m.source_id]));
  const parents = new Map();
  for(const l of ev.links){
    if(l.relation!=="derivation") continue;
    if(!parents.has(l.child)) parents.set(l.child,[]);
    parents.get(l.child).push(l.parent);
  }
  const memo = new Map();
  const visiting = new Set();
  const origins = (mid)=>{
    if(memo.has(mid)) return memo.get(mid);
    if(visiting.has(mid)) throw new Error("cycle at "+mid);
    const ps = parents.get(mid)||[];
    let s;
    if(ps.length===0){ s = new Set([src.get(mid)]); }
    else {
      visiting.add(mid);
      s = new Set();
      for(const pa of ps){ for(const o of origins(pa)) s.add(o); }
      visiting.delete(mid);
    }
    memo.set(mid,s);
    return s;
  };
  const all = new Set();
  for(const m of ev.material_index){ for(const o of origins(m.id)) all.add(o); }
  const qs = c.query_ids.map(q=>({material_id:q, origins:[...origins(q)].sort()}));
  console.log("=====",id);
  console.log("all origins", all.size);
  console.log("details", JSON.stringify(qs));
  // extra diagnostics: roots count, derived items with own source omitted from all
  const roots = ev.material_index.filter(m=>(parents.get(m.id)||[]).length===0);
  const rootSrc = new Set(roots.map(m=>src.get(m.id)));
  console.log("root materials", roots.length, "root sources", rootSrc.size, "diff all vs rootSrc", [...all].filter(x=>!rootSrc.has(x)).length, [...rootSrc].filter(x=>!all.has(x)).length);
  out.push({id, recorded_origin_count:all.size, independence:"unknown", queries:qs});
}
return JSON.stringify({cases:out});

